@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Oswald:wght@400;500;600;700&display=swap');
:root{--paper:#f0e9d8;--orange:#f16a3b;--green:#9dcda0;--ink:#101619;--mono:'DM Mono',monospace;--head:'Oswald','Arial Narrow',sans-serif;--cond:'Barlow Condensed',sans-serif}
*{box-sizing:border-box}html,body{height:100%;margin:0;background:#0d1214;color:var(--paper);font-family:var(--cond);overflow:hidden}body{display:grid;place-items:center}#game-shell{position:relative;width:min(100vw,calc(100vh * 16 / 9));height:min(100vh,calc(100vw * 9 / 16));aspect-ratio:16/9;overflow:hidden;background:#5d7180;box-shadow:0 24px 100px #000b;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}.film-grain{position:absolute;inset:0;pointer-events:none;opacity:.14;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.27'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.topline{position:absolute;top:0;left:0;right:0;height:58px;display:flex;align-items:center;gap:12px;padding:0 27px;background:linear-gradient(#101619dc,#10161900);font:10px var(--mono);letter-spacing:.1em;color:#d4d7cf}.brand-mark{display:grid;place-items:center;width:25px;height:25px;border:1px solid #ee764d;color:#f17a4f;font:700 14px var(--head);transform:rotate(-5deg)}.topline i{height:13px;border-left:1px solid #b2b4a755;margin:0 2px}.radio{margin-left:auto;color:#c9d1c8;font-size:9px}.radio>b{color:#ef7952;font-weight:500}.radio:first-letter{color:#a6d99c}.mission-card{position:absolute;top:85px;left:29px;width:210px;padding:15px 16px 13px;background:linear-gradient(125deg,#111a1ade,#111a1d9c);border-left:2px solid #ed7049;backdrop-filter:blur(4px)}.eyebrow,.hud-label{font:9px var(--mono);letter-spacing:.13em;color:#b1bbaf}.mission-title{font:600 36px/.86 var(--head);letter-spacing:.025em;margin:12px 0 14px;color:#f4efe4}.mission-title em{font-style:normal;color:#ef7952}.mission-progress{height:2px;background:#d1d1c42a;margin-bottom:9px}.mission-progress span{display:block;width:0;height:100%;background:#ef7952;transition:width .3s}.mission-copy{font:9px var(--mono);color:#c1c4b8;letter-spacing:.06em}.mission-copy b{font-size:12px;color:#f38157;margin-right:4px}.mission-copy span{float:right;color:#ee7952;font-size:15px;line-height:9px}.minimap-frame{position:absolute;top:84px;right:28px;width:180px;padding:10px;background:#111a1dde;border:1px solid #d5dcc125;box-shadow:0 4px 20px #0004}.map-label{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.08em;margin:0 0 7px;color:#e8e4d7}.map-label span{color:#a7d29d;font-size:8px}.map-label span:first-letter{color:#a7d29d}.minimap-frame canvas{display:block;width:156px;height:156px;background:#28302e}.map-coords{text-align:center;padding-top:7px;color:#aab1a5;font:7px var(--mono);letter-spacing:.07em}.bottom-hud{position:absolute;left:29px;right:29px;bottom:54px;height:51px;display:flex;align-items:center;justify-content:space-between;padding:8px 13px;background:linear-gradient(90deg,#121a1be8,#121a1ba8 52%,#121a1be8);border-top:1px solid #e6e5d622}.health,.ammo{width:205px}.health-line,.ammo-line{height:25px;display:flex;align-items:center;gap:8px}.cross{font:24px var(--head);color:#8fcb92}.meter{height:4px;background:#ede9d32b;flex:1}.meter i{height:100%;width:100%;display:block;background:#9bd39a;transition:width .2s}.health-line b{font:12px var(--mono);width:29px;text-align:right}.hud-label{font-size:8px}.hud-label small{font-size:7px;color:#909992;margin-left:4px}.ammo{width:160px;text-align:right}.ammo-line{justify-content:flex-end;gap:7px}.ammo-line b{font:25px var(--head);color:#f0eee3}.ammo-line>span:not(.ammo-icon){font:12px var(--mono);color:#a5aaa1}.ammo-line i{font:15px var(--mono);color:#b0b4a8}.ammo-icon{font-size:14px;color:#ed7751;margin-left:6px}.status-pill{font:9px var(--mono);letter-spacing:.08em;color:#c5c6b9}.status-pill i{font-style:normal;color:#e8754f;margin:0 4px}.status-dot{display:inline-block;width:6px;height:6px;background:#a5d19c;border-radius:50%;margin-right:6px;box-shadow:0 0 8px #a5d19c}.controls-hint{position:absolute;bottom:17px;width:100%;text-align:center;color:#e4e0d1b3;font:8px var(--mono);letter-spacing:.06em}.controls-hint kbd{font:8px var(--mono);border:1px solid #eee8d84c;border-radius:2px;padding:3px 4px;margin:0 2px;color:#f0ebdc}.controls-hint span{color:#ed7951;margin:0 4px}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#0d1414db,#11191976 54%,#12161670),linear-gradient(0deg,#1014165c,transparent 55%);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-panel{width:390px;margin-top:8px}.patch{font:9px var(--mono);letter-spacing:.13em;color:#dedccd;border-left:2px solid #ed744d;padding:5px 0 5px 9px;margin-bottom:28px}.patch span{color:#ef794d;font-size:13px;margin-left:5px}.title-kicker{font:11px var(--mono);letter-spacing:.16em;color:#e8ddc4}.overlay h1{margin:8px 0 12px;font:700 76px/.82 var(--head);letter-spacing:-.02em;color:#f2ecdd;text-shadow:0 3px 15px #10131370}.overlay h1 em{font-style:normal;color:#ef7952}.overlay-panel p{font:15px var(--cond);letter-spacing:.04em;color:#d1d0c4;margin:22px 0 24px}.overlay-panel button{height:47px;width:206px;border:0;background:#eb7049;color:#111615;display:flex;align-items:center;justify-content:space-between;padding:0 15px;font:600 12px var(--mono);letter-spacing:.09em;cursor:pointer;transition:background .15s,transform .15s}.overlay-panel button:hover{background:#ff895b;transform:translateY(-2px)}.overlay-panel button b{font-size:19px;font-weight:400}.overlay-foot{margin-top:19px;font:8px var(--mono);letter-spacing:.06em;color:#c5c8bb}.overlay-foot i{font-style:normal;color:#ed794f;margin:0 7px}.overlay-bottom{position:absolute;bottom:20px;left:27px;right:27px;display:flex;justify-content:space-between;color:#d5d4c38a;font:8px var(--mono);letter-spacing:.12em}.objective-toast{position:absolute;left:50%;top:31%;transform:translate(-50%,-10px);padding:12px 19px;background:#101817e6;border-left:2px solid #a6d19c;font:11px var(--mono);letter-spacing:.1em;opacity:0;transition:.3s;white-space:nowrap}.objective-toast span{color:#a9b5a6;font-size:9px}.objective-toast.show{opacity:1;transform:translate(-50%,0)}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:24px var(--head);color:#f5e9d1;opacity:0;transition:transform .08s,opacity .12s;text-shadow:0 1px 5px #000}.hit-marker.show{opacity:1;transform:translate(-50%,-50%) scale(1)}#mobile-controls{display:none}.damage-flash{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px 25px #c34a3666;animation:flash .25s ease-out}@keyframes flash{from{opacity:1}to{opacity:0}}@media(max-width:700px){#game-shell{width:100vw;height:100dvh;aspect-ratio:auto}.topline{height:43px;padding:0 12px;font-size:8px}.brand-mark{width:21px;height:21px}.mission-card{left:12px;top:57px;width:150px;padding:10px}.mission-title{font-size:27px;margin:8px 0 10px}.eyebrow{font-size:7px}.mission-copy{font-size:7px}.minimap-frame{top:55px;right:10px;width:120px;padding:7px}.minimap-frame canvas{width:104px;height:104px}.map-label{font-size:7px}.map-coords{font-size:6px}.bottom-hud{left:10px;right:10px;bottom:111px;height:45px;padding:5px 8px}.health{width:34%}.ammo{width:28%}.status-pill{font-size:0}.status-pill i{font-size:9px}.health-line{gap:4px}.cross{font-size:19px}.health-line b{font-size:10px}.ammo-line{gap:4px}.ammo-line b{font-size:21px}.hud-label{font-size:7px}.controls-hint{display:none}.overlay-panel{width:290px}.overlay h1{font-size:64px}.overlay-panel p{font-size:13px}.overlay-foot{font-size:7px}.overlay-bottom{left:10px;right:10px;font-size:6px}.objective-toast{top:27%;font-size:9px}.objective-toast span{font-size:7px}.mobile-pad{position:absolute;left:14px;bottom:15px;display:grid;gap:3px}.mobile-pad>button{margin:auto}.mobile-pad div{display:flex;gap:3px}.mobile-pad button,.mobile-actions button{width:38px;height:38px;border:1px solid #efe9d34c;background:#10181799;color:#f4ead7;border-radius:5px;font:16px var(--mono);touch-action:none}.mobile-actions{position:absolute;right:15px;bottom:20px;display:flex;gap:8px;align-items:end}.mobile-actions button:first-child{width:58px;height:58px;background:#e96e48d9;border:0;font:10px var(--mono);font-weight:bold}.mobile-actions button:last-child{width:40px;height:40px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d', { alpha: false });
  const mini = document.getElementById('minimap'), mctx = mini.getContext('2d');
  const W = 640, H = 360, horizon = 154;
  canvas.width = W; canvas.height = H;
  const TAU = Math.PI * 2, FOV = Math.PI / 2.85;
  const player = { x: 3.7, y: 3.5, a: 0, health: 100, ammo: 12, reserve: 48, score: 0 };
  let started = false, gameOver = false, remaining = 6, lastTime = 0, fireTimer = 0, recoil = 0, damageFlash = 0, reloadTimer = 0, toastTimer = 0;
  const keys = Object.create(null), depth = new Float32Array(W), enemies = [], pickups = [];
  const walkTouches = new Set();
  const ui = {
    overlay: document.getElementById('overlay'), start: document.getElementById('start-button'),
    targets: document.getElementById('targets-left'), progress: document.getElementById('progress-fill'),
    health: document.getElementById('health-fill'), healthNum: document.getElementById('health-number'),
    ammo: document.getElementById('ammo-now'), reserve: document.getElementById('ammo-reserve'),
    toast: document.getElementById('toast'), hit: document.getElementById('hit-marker')
  };
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const fract = x => x - Math.floor(x);
  const hash = (x, y) => fract(Math.sin(x * 127.1 + y * 311.7) * 43758.5453);
  const cellSolid = (x, y) => fract(x / 14) > 8 / 14 && fract(y / 14) > 8 / 14;
  const buildingStyle = (x, y) => (Math.floor(x / 14) * 7 + Math.floor(y / 14) * 11 + 180) % 8;

  function makeFacade(style) {
    const c = document.createElement('canvas'); c.width = 128; c.height = 256;
    const g = c.getContext('2d');
    const bricks = ['#785e4c','#756b5c','#6a5549','#777267','#624e47','#6e6256','#7a6656','#555754'];
    const base = bricks[style];
    g.fillStyle = base; g.fillRect(0,0,128,256);
    g.fillStyle = 'rgba(25,27,25,.22)';
    for (let y=0;y<256;y+=18) { g.fillRect(0,y,128,2); for(let x=(y/18%2)*12;x<128;x+=24)g.fillRect(x,y,1,18); }
    const warm = ['#d7b57b','#91a79b','#d0a47c','#8da4a5','#c59773','#9ca17e','#d1b188','#a8aba2'][style];
    for (let fy=0;fy<4;fy++) for(let fx=0;fx<2;fx++) {
      const x=12+fx*58, y=12+fy*59;
      g.fillStyle='#252a29';g.fillRect(x-3,y-3,35,43);
      g.fillStyle='#46504f';g.fillRect(x,y,29,37);
      const lit=hash(style*17+fx,fy)>.42;
      g.fillStyle=lit?warm:'#293d45';g.fillRect(x+3,y+4,23,29);
      if(lit){g.fillStyle='rgba(255,230,177,.32)';g.fillRect(x+3,y+4,23,5);g.fillStyle='rgba(27,30,30,.8)';g.fillRect(x+13,y+4,2,29);}
      g.fillStyle='#554f43';g.fillRect(x-4,y+37,37,4);g.fillRect(x-4,y-4,37,4);
    }
    g.fillStyle='rgba(24,27,26,.55)';
    for(let i=0;i<5;i++){const x=i*27-3;g.fillRect(x,0,2,256);}
    if(style===1||style===5){g.strokeStyle='#282c29';g.lineWidth=3;for(let y=35;y<220;y+=40){g.beginPath();g.moveTo(5,y);g.lineTo(123,y);g.lineTo(119,y+17);g.stroke();}for(let x=10;x<128;x+=35){g.beginPath();g.moveTo(x,30);g.lineTo(x,226);g.stroke();}}
    if(style===2||style===6){g.fillStyle='#d5c7a6';g.fillRect(4,224,120,21);g.fillStyle='#bd5038';g.fillRect(8,228,112,13);g.fillStyle='#e7d8b8';g.font='bold 9px monospace';g.fillText(style===2?'DELI   OPEN 24H':'HOTEL  ★★★',13,238);}
    g.fillStyle='rgba(12,17,18,.2)';g.fillRect(0,0,128,256);
    return c;
  }
  const facades = Array.from({length:8},(_,i)=>makeFacade(i));

  function drawSky() {
    const grad=ctx.createLinearGradient(0,0,0,horizon+38);
    grad.addColorStop(0,'#72899a'); grad.addColorStop(.58,'#b2a898'); grad.addColorStop(1,'#e1b688');
    ctx.fillStyle=grad;ctx.fillRect(0,0,W,horizon+45);
    // Far skyline haze and rooftops between close buildings.
    for(let i=0;i<22;i++){
      const x=((i*97 - player.x*8 + 4800)%820)-90, h=13+hash(i,8)*49;
      ctx.fillStyle=i%3===0?'#697578':'#788180';ctx.fillRect(x,horizon-h,x%3+23,h);
      ctx.fillStyle='#91918a';for(let j=0;j<3;j++)ctx.fillRect(x+3+j*6,horizon-h+5,3,7);
    }
    ctx.fillStyle='rgba(241,195,139,.27)';ctx.fillRect(0,horizon-4,W,34);
  }
  function floorPixel(x,y,dist) {
    const a=player.a+(x/W-.5)*FOV;
    const wx=player.x+Math.cos(a)*dist, wy=player.y+Math.sin(a)*dist;
    const fx=fract(wx/14), fy=fract(wy/14), roadX=fx<8/14, roadY=fy<8/14;
    let r,g,b;
    if(roadX&&roadY){r=57;g=59;b=55;
      // Manhattan's broken double-yellow line on avenues.
      if(Math.abs(fy-4/14)<.010){r=177;g=151;b=77;}
      if(Math.abs(fx-4/14)<.009){r=166;g=142;b=71;}
      const crossX=fx<.095||fx>.905, crossY=fy<.095||fy>.905;
      if((crossX||crossY)&& (Math.abs(fx-.08)<.019||Math.abs(fy-.08)<.019)){r=195;g=186;b=157;}
      // manholes and faint asphalt grain
      if(fract(wx*.21)<.09&&fract(wy*.21)<.08){r+=8;g+=7;b+=6;}
    }else if(!roadX&&!roadY){r=81;g=76;b=67;}
    else {r=119;g=111;b=94;
      if(Math.abs(fx-8/14)<.01||Math.abs(fy-8/14)<.01){r=166;g=154;b=127;}
      const joints=(Math.abs(fract(wx)-.04)<.016||Math.abs(fract(wy)-.04)<.016);
      if(joints){r-=15;g-=13;b-=10;}
    }
    const shade=clamp(1.02-dist*.009, .36, 1)*(.94+hash(Math.floor(wx*2),Math.floor(wy*2))*.12);
    const p=(y*W+x)*4;pixels[p]=r*shade;pixels[p+1]=g*shade;pixels[p+2]=b*shade;pixels[p+3]=255;
  }
  const frame=ctx.createImageData(W,H), pixels=frame.data;
  function renderFloor() {
    for(let y=horizon+1;y<H;y++){
      const dist=(H*.48)/(y-horizon);
      if(dist>54)continue;
      for(let x=0;x<W;x+=2){floorPixel(x,y,dist);floorPixel(x+1,y,dist);}
    }
    ctx.putImageData(frame,0,0);
  }
  function castRay(angle) {
    const dx=Math.cos(angle),dy=Math.sin(angle), mapX=Math.floor(player.x),mapY=Math.floor(player.y);
    const deltaX=Math.abs(1/dx),deltaY=Math.abs(1/dy);
    const stepX=dx<0?-1:1,stepY=dy<0?-1:1;
    let sideX=dx<0?(player.x-mapX)*deltaX:(mapX+1-player.x)*deltaX;
    let sideY=dy<0?(player.y-mapY)*deltaY:(mapY+1-player.y)*deltaY;
    let mx=mapX,my=mapY,side=0,dist=0;
    for(let i=0;i<160;i++){
      if(sideX<sideY){sideX+=deltaX;mx+=stepX;side=0;dist=sideX-deltaX;}
      else{sideY+=deltaY;my+=stepY;side=1;dist=sideY-deltaY;}
      if(dist>54)break;
      if(cellSolid(mx+.5,my+.5)){const hit=side===0?player.y+dist*dy:player.x+dist*dx;return {dist,side,u:fract(hit),mx,my,style:buildingStyle(mx,my)};}
    }
    return {dist:54,side:0,u:0,mx:0,my:0,style:0};
  }
  function renderWalls() {
    const step=2;
    for(let x=0;x<W;x+=step){
      const angle=player.a+(x/W-.5)*FOV, hit=castRay(angle), corrected=hit.dist*Math.cos(angle-player.a);
      for(let k=0;k<step;k++)depth[x+k]=corrected;
      const blockHeight=3.1+hash(Math.floor(hit.mx/14),Math.floor(hit.my/14))*2.2;
      const wallH=Math.min(H*2,H*1.04*blockHeight/corrected);
      const top=Math.max(0,Math.floor(horizon-wallH*.53)),bottom=Math.min(H,Math.floor(horizon+wallH*.47));
      const facade=facades[hit.style], sx=Math.min(127,Math.floor(hit.u*128));
      ctx.globalAlpha=hit.side===1?.79:.97;
      ctx.drawImage(facade,sx,0,1,256,x,top,step,bottom-top);
      ctx.globalAlpha=1;
      // warm sky-light along the cornice and dark ground contact.
      ctx.fillStyle='rgba(237,194,139,.18)';ctx.fillRect(x,top,step,Math.max(1,wallH*.025));
      ctx.fillStyle='rgba(10,13,13,.28)';ctx.fillRect(x,bottom-2,step,2);
      if(corrected>19){ctx.fillStyle=`rgba(190,191,174,${Math.min(.3,(corrected-19)*.009)})`;ctx.fillRect(x,top,step,bottom-top);}
    }
  }

  function makeEnemy(x,y,variant=0){return {x,y,hp:2,alive:true,variant,phase:Math.random()*6,shot:1.5+Math.random()*2,hit:0};}
  function seedEnemies(){
    enemies.length=0;
    [[9.5,3.8],[3.8,9.5],[18.5,3.7],[3.6,18.5],[10.5,18.4],[18.6,10.5]].forEach((p,i)=>enemies.push(makeEnemy(...p,i%4)));
    pickups.length=0;
  }
  seedEnemies();

  function drawEnemy(e,now){
    if(!e.alive)return;
    let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),angle=Math.atan2(dy,dx)-player.a;
    while(angle>Math.PI)angle-=TAU;while(angle<-Math.PI)angle+=TAU;
    if(Math.abs(angle)>FOV*.62||dist<.25)return;
    const sx=(.5+angle/FOV)*W, size=clamp(H*1.14/dist,3,118), base=horizon+size*.51;
    if(sx<0||sx>=W||dist>depth[clamp(Math.floor(sx),0,W-1)]+.3)return;
    const bob=Math.sin(now*.004+e.phase)*size*.012, x=sx, s=size;
    ctx.save();ctx.translate(x,base+bob);
    const leg='#292b2a', shirt=['#596458','#6a4035','#515d68','#7b654a'][e.variant];
    ctx.fillStyle='rgba(13,16,15,.35)';ctx.beginPath();ctx.ellipse(0,0,s*.18,s*.045,0,0,TAU);ctx.fill();
    // legs, boots
    ctx.fillStyle=leg;ctx.fillRect(-s*.105,-s*.31,s*.075,s*.28);ctx.fillRect(s*.03,-s*.31,s*.075,s*.28);
    ctx.fillStyle='#171b1b';ctx.fillRect(-s*.12,-s*.06,s*.09,s*.045);ctx.fillRect(s*.02,-s*.06,s*.10,s*.045);
    // torso, shoulders, collar
    ctx.fillStyle=shirt;ctx.fillRect(-s*.15,-s*.69,s*.30,s*.38);ctx.fillRect(-s*.21,-s*.65,s*.11,s*.27);ctx.fillRect(s*.10,-s*.65,s*.11,s*.27);
    ctx.fillStyle='#d2aa84';ctx.fillRect(-s*.045,-s*.76,s*.09,s*.10);
    ctx.fillStyle=['#a36c4c','#bd916d','#835f48','#c19b75'][e.variant];ctx.beginPath();ctx.arc(0,-s*.82,s*.105,0,TAU);ctx.fill();
    ctx.fillStyle='#272927';ctx.beginPath();ctx.arc(0,-s*.85,s*.115,Math.PI,TAU);ctx.fill();ctx.fillRect(-s*.11,-s*.86,s*.22,s*.035);
    // aimed dark service pistol
    ctx.strokeStyle='#292d2b';ctx.lineWidth=Math.max(1,s*.035);ctx.beginPath();ctx.moveTo(s*.1,-s*.59);ctx.lineTo(s*.29,-s*.68);ctx.stroke();ctx.fillStyle='#272a28';ctx.fillRect(s*.24,-s*.705,s*.13,s*.042);
    if(e.hit>0){ctx.strokeStyle=`rgba(255,224,179,${e.hit})`;ctx.lineWidth=2;ctx.strokeRect(-s*.2,-s*.94,s*.4,s*.92);}
    ctx.restore();
    if(e.hp===1){const bw=s*.32;ctx.fillStyle='#171c1b';ctx.fillRect(sx-bw/2,base-s*1.06,bw,2);ctx.fillStyle='#ed7650';ctx.fillRect(sx-bw/2,base-s*1.06,bw*.55,2);}
  }
  function render(now){
    drawSky();renderFloor();renderWalls();
    enemies.filter(e=>e.alive).sort((a,b)=>Math.hypot(b.x-player.x,b.y-player.y)-Math.hypot(a.x-player.x,a.y-player.y)).forEach(e=>drawEnemy(e,now));
    drawWeapon();drawMinimap();
  }
  function drawWeapon(){
    const recoilY=recoil*14;
    ctx.save();ctx.translate(W*.5,H+10+recoilY);
    // illustrated hand and compact service sidearm in the foreground
