31:     g.fillStyle = 'rgba(25,27,25,.22)';
32:     for (let y=0;y<256;y+=18) { g.fillRect(0,y,128,2); for(let x=(y/18%2)*12;x<128;x+=24)g.fillRect(x,y,1,18); }
33:     const warm = ['#d7b57b','#91a79b','#d0a47c','#8da4a5','#c59773','#9ca17e','#d1b188','#a8aba2'][style];
34:     for (let fy=0;fy<4;fy++) for(let fx=0;fx<2;fx++) {
